insert into public.guide_revision_archive(guide_id,revision,content) values
('m50-engine-oil-and-filter','48717ea08c611c9763335dc9','{"engines":["M50","M50TU"],"level":"Intermediate","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"m50-engine-oil-and-filter","jobSupport":{"reviewedOn":"2026-11-09","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Matched cartridge with all applicable cover/center-bolt O-rings","New metal drain-plug sealing washer","Engine oil appropriate to the installed engine, current product guidance and operating conditions"],"conditionalParts":["Damaged plug or filter-cover hardware only after matching the actual housing/thread","Replacement seals omitted from a chosen filter kit must be sourced separately"],"stopConditions":["Unsafe lifting/support or access","Oil too hot to handle safely","Damaged threads or sealing face","Unknown plug/cover specification","Pressure warning remains on after start","New active leak"],"steps":[{"number":1,"tools":["Light","Matching source/part instructions"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":2,"tools":["Drain pan","Matching socket or box wrench","Gloves","Torque wrench"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":3,"tools":["Matching cover tool","Lint-free cloth","Torque wrench"],"source":{"printed":"020-9","pdf":31,"href":"/manual/020?pdf=31"}},{"number":4,"tools":["Funnel","Dipstick","Oil container"],"source":{"printed":"020-8","pdf":30,"href":"/manual/020?pdf=30"}},{"number":5,"tools":["Driver-visible warning lamp","Light","Dipstick"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}}]},"title":"Change the oil and cartridge filter on an M50 525i","system":"engine","kind":"replacement","duration":"45–75 min","summary":"Drain the engine oil, renew the cartridge and seals, then verify oil pressure, level and leaks before driving.","applicability":"U.S. E34 525i with an installed M50 or M50TU and factory-type sump and cartridge housing. Confirm the actual drain plug and filter lid hardware. The M20 spin-on filter and aftermarket sump or housing hardware use different instructions.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-8 to 020-10, Table e and Figs. 3–4","pdfPages":[30,31,32]},"tools":["Correct cartridge and seal kit","New drain-plug sealing washer","Suitable engine oil","Drain pan and funnel","Sockets, torque wrench and clean lint-free cloths","Oil-resistant gloves and eye protection"],"cautions":["Use firm, level ground and immobilize the car. Never get under a car supported only by a jack. If you need to lift it, use the approved lifting and support points and the procedure in Bentley 010.","Warm oil drains quickly and can burn. Keep hands clear of the stream. Let the oil cool enough to handle safely.","If the pressure warning stays on after starting, shut the engine off immediately and resolve the cause before restarting."],"steps":[{"title":"Confirm the filter, seals and tightening values","body":"Identify the sump drain plug and the actual cartridge cover fastener before opening either. Bentley 020-9 lists 25 Nm for an original M12 sump plug and 60 Nm for M22. It lists 33 Nm for an M10/M12 filter-cover bolt and 25 Nm for a screw-on cover. These are different fasteners. Confirm the installed hardware and use its applicable instructions if it differs.","check":"The drain plug and cover each have their own confirmed value, and the filter, new washer and all applicable O-rings are on hand."},{"title":"Drain the sump and refit the plug","body":"Warm the engine briefly, switch it off and position the pan to catch the full stream. Identify the engine sump independently of the transmission. Release the plug, drain the oil and clean the mating face. Install the plug by hand with its new washer, then tighten to the confirmed value.","check":"The plug started cleanly by hand and the new washer is seated. A damaged thread or sealing face stops the job."},{"title":"Replace the cartridge and seals","body":"Remove the filter cover and lift out the old cartridge. Note the exact grooves for the cover and center-bolt seals, where fitted. Replace each old seal, lubricate the new seals with clean engine oil and seat the new element. Refit and tighten the cover using the confirmed value for that housing.","check":"No old seal remains in a groove. Each new seal sits flat and the lid is fully seated."},{"title":"Refill by the dipstick","body":"With the car level, add suitable oil in stages. Bentley lists about 5.75 L for the M50 with a filter change. Residual oil and hardware changes affect the amount needed. Check the dipstick after the oil settles and leave the reading within the marked range before starting.","check":"Filler cap and dipstick are in place and the level is in range."},{"title":"Check pressure, leaks and final level","body":"Start from the driver’s seat and watch the oil pressure warning. Stop immediately if it stays on. Once normal pressure is indicated, check for fresh leaks from a safe position. Switch off, allow the oil to settle, recheck on level ground and correct the level in small amounts. Recycle the used oil and filter at an appropriate collection point.","check":"Warning clears, drain and housing are dry, and the final dipstick reading is in range."}]}'::jsonb),
('m50-spark-plug-replacement','d8598811b27f793cfb09d32d','{"slug":"m50-spark-plug-replacement","title":"Replace the M50 or M50TU spark plugs","system":"engine","jobSupport":{"reviewedOn":"2026-11-09","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Six matching plugs selected against the installed head/ignition application and current plug-maker guidance"],"conditionalParts":["Damaged boots, coils or connector parts after diagnosis","Valve-cover/plug-well leak repair if standing oil is found"],"stopConditions":["Unconfirmed current plug specification","Standing oil/water or unresolved debris in well","Binding/cross-threading","Damaged boot, coil or connector","New misfire after reassembly"],"steps":[{"number":1,"tools":["Current plug-maker application/install information","Inspection light"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":2,"tools":["Matching small sockets","Extension","Labels/camera","Parts tray","Matching sockets","Light","Appropriate non-damaging well-cleaning equipment"],"source":{"printed":"020-10","pdf":32,"href":"/manual/020?pdf=32"}},{"number":3,"tools":["Correct spark-plug socket","Straight extension","Parts tray"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}},{"number":4,"tools":["Spark-plug socket/extension","Suitable calibrated torque wrench"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}},{"number":5,"tools":["Matching sockets","Light"],"source":{"printed":"020-11","pdf":33,"href":"/manual/020?pdf=33"}}],"additionalSources":[{"title":"NGK plated-plug installation: dry threads; no added lubricant","url":"https://ngksparkplugs.com/en/resources/5-things-you-should-know-about-spark-plugs"}]},"engines":["M50","M50TU"],"level":"Intermediate","kind":"replacement","duration":"45–75 min","summary":"Remove the individual coils, inspect the plug wells and replace the plugs with a verified set for the installed cylinder head.","applicability":"U.S. E34 525i with the original M50 or M50TU coil-on-plug system. Use the correct plugs for the actual head and ignition system.","searchTerms":"spark plug change misfire plugs tune up ignition coil m50 m50tu","tools":["Correct plug set","Spark plug socket and straight extension","Torque wrench","Light and clean vacuum"],"cautions":["Work with the engine cold and the ignition off. Confirm the plug maker’s installation and torque instructions for the exact plug, especially dry versus lubricated threads.","Stop for pooled oil, damaged threads or cracked coil boots. Keep debris out of open plug holes."],"relatedGuides":["m50-valve-cover-gasket"],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-10–020-11, Table f","pdfPages":[32,33]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Confirm plug fit and reach","body":"Match the plug part number, seat and gap specification to the installed engine. Check the plug maker’s guidance before adjusting a fine-wire electrode.","check":"All six plugs match the application and the correct installation specification is on hand."},{"title":"Expose the coils and record their wiring","body":"Remove the coil cover. Note the connectors, ground straps and brackets. Release the connectors using their catches and lift each coil straight up after removing its hardware. Label the cylinders from the front of the engine.","check":"No coil boot or harness terminal is torn and grounds are accounted for."},{"title":"Inspect each well before removing the plug","body":"Look for standing oil, water and grit. Clean the well before opening it. Use a straight plug socket and extension. Keep the removed plugs in cylinder order if diagnosing a misfire.","check":"The wells are clean and plug condition can be traced to a cylinder."},{"title":"Start threads by hand and seat the plugs","body":"Lower each plug into the well with the socket and start it by hand. If it binds, back it out and inspect the threads. Use the current plug maker’s torque and thread-condition instructions for the exact replacement. Bentley’s historical 30 Nm figure assumes lightly oiled threads; it must not be transferred to a plated plug that the maker specifies installing dry. NGK instructs that its plated plugs receive no added lubricant or anti-seize.","check":"The plugs are seated without cross-threading and tightened using the exact plug’s specified installation condition."},{"title":"Reconnect and check idle","body":"Seat each coil boot, refit coil hardware and grounds, latch the connectors and replace the cover. Start the engine and check for a steady idle. If it misfires, shut down and inspect the affected coil connections and plug fit before running it again.","check":"All connectors are latched and there is no new misfire."}]}'::jsonb),
('m50-valve-cover-gasket','57ca10bf89688aa0724600eb','{"slug":"m50-valve-cover-gasket","title":"Replace the M50 valve-cover gasket","system":"engine","jobSupport":{"reviewedOn":"2026-11-09","sourceSha256":"23032c541d08d764921449cb13751e77847abaeb720abb21e30401e22797322a","requiredParts":["Matching perimeter gasket","Matching plug-well seals"],"conditionalParts":["Correct fastener insulators/grommets if deteriorated or required by the selected kit instructions","Breather fitting/connector or cover only if damage is found","Sealant only at locations and cure conditions specified for the actual gasket/cover product"],"stopConditions":["Wrong/uncertain cover or kit","Cracked/distorted cover or damaged mating face","Brittle fitting that cannot release normally","Unremoved fastener or force required to lift cover","Missing ground/bracket/hardware record","Gasket will not remain seated","Continued oil leak or abnormal running"],"steps":[{"number":1,"tools":["Light","Cleaning cloth","Current gasket/cover instructions","Matching battery tool","Work record"],"source":{"printed":"116-3","pdf":101,"href":"/manual/116?pdf=101"}},{"number":2,"tools":["Appropriate fitting/trim tool","Matching sockets","Parts tray","Labels/camera","Matching sockets and extension"],"source":{"printed":"116-3","pdf":101,"href":"/manual/116?pdf=101"}},{"number":3,"tools":["Matching sockets","Non-marring cleaning tool","Lint-free cloth"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}},{"number":4,"tools":["Light/mirror","Selected product instructions"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}},{"number":5,"tools":["Low-range torque wrench","Matching sockets","Light","Work record"],"source":{"printed":"116-4","pdf":102,"href":"/manual/116?pdf=102"}}]},"engines":["M50","M50TU"],"level":"Intermediate","kind":"replacement","duration":"1–3 hours","summary":"Reseal the factory cam cover and spark plug wells while preserving coil grounds, cover seals and the specified joint treatment.","applicability":"Bentley-covered E34 525i with an original M50/M50TU head and cover. Verify the gasket kit, cover type and applicable sealing points. Oil from above the cover or a damaged cover needs a separate repair.","searchTerms":"valve cover cam cover rocker cover gasket plug wells oil leak m50","tools":["Matching perimeter gasket and spark plug well seals","Correct fastener insulators","Low-range torque wrench","Non-marring scraper"],"cautions":["Work cold with the battery isolated according to the vehicle procedure. Keep tools, old gasket and solvent clear of exposed valve gear.","A gasket cannot correct a distorted cover or a damaged sealing face."],"durationBasis":"Editorial estimate for an accessible, source-matching installation.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"116-3–116-4, M50 cylinder head cover","pdfPages":[101,102]},"reviewStatus":"draft","sourceChecked":true,"steps":[{"title":"Verify the leak and gather matching seals","body":"Clean the suspected area and trace fresh oil. Identify the perimeter seal, plug-well seals and fastener insulators against the actual cover before disassembly.","check":"The leak points to the cover joint or plug wells and the kit fits the cover."},{"title":"Disconnect cover attachments","body":"Remove the covers and ignition coils. Photograph the ground straps and their studs, release the breather at its fitting, and move the wiring aside with support. Record fastener insulator placement.","check":"The harness, grounds and breather are free without breaking a fitting."},{"title":"Lift the cover and prepare the mating surfaces","body":"Lift the cover evenly and remove the seals. Inspect the cover, plug-well grooves and head joints. Use a non-marring tool and keep old sealant out of the head. Clean and dry the sealing faces.","check":"The groove and surfaces are clean, with no cracks or damaged sealing edge."},{"title":"Install seals and seat the cover","body":"Install the perimeter and well seals without stretching. Use sealant only where the gasket or vehicle instructions specify it. Lower the cover squarely and verify that the rear gasket contour and well seals stay seated.","check":"The gasket remains in the groove all the way around and no wire is trapped."},{"title":"Tighten and confirm the repair","body":"Refit the insulators and tighten the source-matching cover hardware progressively and evenly to the listed 10 Nm. Restore every ground, coil and breather connection. Observe any sealant cure interval, then check the perimeter and wells for fresh oil and recheck after a heat cycle.","check":"The engine runs normally and the repaired seam stays dry."}]}'::jsonb)
